inline constexpr size_t kInsnCount = sizeof(kInsns) / sizeof(kInsns[0]);

// Returns the matching instruction or nullptr. The generator guarantees no
// 32-bit word matches more than one entry (see verify_isa.py).
inline const InsnInfo* Decode(uint32_t insn) {
  for (size_t i = 0; i < kInsnCount; ++i)
    if ((insn & kInsns[i].mask) == kInsns[i].match) return &kInsns[i];
  return nullptr;
}

// VMX128 / AltiVec operand extraction (see FIELDS in build_isa.py).
constexpr uint32_t VD(uint32_t i)    { return (i >> 21) & 0x1F; }
constexpr uint32_t VA(uint32_t i)    { return (i >> 16) & 0x1F; }
constexpr uint32_t VB(uint32_t i)    { return (i >> 11) & 0x1F; }
constexpr uint32_t VC(uint32_t i)    { return (i >> 6) & 0x1F; }
constexpr uint32_t VD128(uint32_t i) { return ((i >> 21) & 0x1F) | ((i << 3) & 0x60); }
constexpr uint32_t VA128(uint32_t i) { return ((i >> 16) & 0x1F) | (i & 0x20) | ((i >> 4) & 0x40); }
constexpr uint32_t VB128(uint32_t i) { return ((i >> 11) & 0x1F) | ((i << 5) & 0x60); }
constexpr uint32_t VC128(uint32_t i) { return (i >> 6) & 0x7; }
constexpr uint32_t VPERM128(uint32_t i) { return ((i >> 16) & 0x1F) | ((i >> 1) & 0xE0); }
constexpr uint32_t SHB(uint32_t i)   { return (i >> 6) & 0xF; }
constexpr uint32_t VD3D0(uint32_t i) { return (i >> 18) & 0x7; }
constexpr uint32_t VD3D1(uint32_t i) { return (i >> 16) & 0x3; }
constexpr uint32_t VD3D2(uint32_t i) { return (i >> 6) & 0x3; }

